import{_ as e,o as l,c as i,a2 as r}from"./chunks/framework.mzJ8I8R4.js";const u=JSON.parse('{"title":"在本机使用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/local.md","filePath":"guide/local.md"}'),o={name:"guide/local.md"};function t(n,a,d,h,s,p){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="在本机使用" tabindex="-1">在本机使用 <a class="header-anchor" href="#在本机使用" aria-label="Permalink to &quot;在本机使用&quot;">​</a></h1><p>不部署服务器也能用：Android、iOS、macOS 和 Windows App 可以只在本机使用，不用注册账号，数据存在这台设备上。几台设备之间可以<a href="#drive">借网盘同步</a>。</p><h2 id="和连接服务器的区别" tabindex="-1">和连接服务器的区别 <a class="header-anchor" href="#和连接服务器的区别" aria-label="Permalink to &quot;和连接服务器的区别&quot;">​</a></h2><ul><li><strong>同步</strong>：默认不同步，每台设备的数据各自独立。<a href="#drive">借网盘同步</a>时，改动几十秒内到别的设备，不是实时。</li><li><strong>没有网页版</strong>：网页版只能连接服务器。</li><li><strong>没有共享文件夹和多账号</strong>：只有自己一个人用。</li><li><strong>agent</strong>：只能在电脑上接入，见<a href="./agent#在本机使用时">接入 agent</a>。手机上不能。</li><li><strong>AI 整理</strong>：配置只保存在这台设备上。</li><li><strong>更新</strong>：App 从 GitHub 获取新版本。</li></ul><p>其余功能完全一样。</p><h2 id="开始" tabindex="-1">开始 <a class="header-anchor" href="#开始" aria-label="Permalink to &quot;开始&quot;">​</a></h2><p>第一次打开 App 时选“在本机使用”即可。已经登录了服务器的，先在“设置 → 账号”最下方退出登录，再在登录页选“在本机使用”。</p><h2 id="drive" tabindex="-1">借网盘同步 <a class="header-anchor" href="#drive" aria-label="Permalink to &quot;借网盘同步 {#drive}&quot;">​</a></h2><p>手机和电脑都在本机使用时，可以借一个网盘在它们之间同步，不用部署服务器。支持 WebDAV 网盘（如坚果云）和 S3 兼容的对象存储（如 MinIO）。开启时会先检查这个网盘能不能用来同步，不能用的会提示原因。</p><h3 id="第一台设备" tabindex="-1">第一台设备 <a class="header-anchor" href="#第一台设备" aria-label="Permalink to &quot;第一台设备&quot;">​</a></h3><ol><li>打开“设置”，点最上面的“本机模式”，再点“借网盘同步”。</li><li>选择网盘，填好下面几项： <ul><li><strong>WebDAV</strong>：地址、用户名、密码。坚果云的地址已经填好，不用改；密码要用坚果云的应用密码，不是登录密码，见下文。</li><li><strong>S3</strong>：接口地址、区域、存储桶、Access Key ID 和 Secret Access Key。“地址风格”一般不用改，MinIO 这类自建的选“路径”。存储桶不能开启版本控制，否则无法同步。</li><li><strong>文件夹</strong>：数据放在网盘里的这个文件夹，默认是 <code>NextTodo</code>，不存在会自动新建。要用一个空文件夹。</li></ul></li><li>点“开启同步”。这台设备上的数据会传到网盘里。</li></ol><h3 id="其他设备" tabindex="-1">其他设备 <a class="header-anchor" href="#其他设备" aria-label="Permalink to &quot;其他设备&quot;">​</a></h3><p>在其他设备上按同样的步骤，填同一个网盘和同一个文件夹。开启时会提示“用网盘里的数据替换这台设备上的全部数据？”，确认后 App 重新启动，换上网盘里的数据。这台设备原来的数据不会合并进去，所以先在数据最全的那台设备上开启。电脑上接入过 agent 的，换上网盘里的数据后要重新生成令牌。</p><h3 id="坚果云的应用密码" tabindex="-1">坚果云的应用密码 <a class="header-anchor" href="#坚果云的应用密码" aria-label="Permalink to &quot;坚果云的应用密码&quot;">​</a></h3><ol><li>用浏览器登录<a href="https://www.jianguoyun.com" target="_blank" rel="noreferrer">坚果云网页版</a>，点右上角的账户名，进“账户信息”。</li><li>打开“安全选项”，在“第三方应用管理”里点“添加应用密码”，名称随便写（比如 NextTodo），点“生成密码”。</li><li>用户名填坚果云的登录邮箱，密码填刚生成的应用密码。</li></ol><p>坚果云的免费版限制了请求次数和每月的流量。每台设备平时 30 秒查一次，几台设备一起用也在免费版的限额以内；附件最占流量。</p><h3 id="使用时" tabindex="-1">使用时 <a class="header-anchor" href="#使用时" aria-label="Permalink to &quot;使用时&quot;">​</a></h3><ul><li>改动在这台设备上立即生效，几十秒内同步到别的设备；App 回到前台时会马上同步一次。没联网时照常使用，联网后自动补上。</li><li>别的设备添加的附件，第一次打开时才从网盘下载。</li><li>“设置”里的本机模式卡片写着同步到哪个网盘、上次同步的时间，出错时写明原因。</li><li>网盘里的数据不加密，网盘的服务商看得到内容。</li></ul><h3 id="停止同步" tabindex="-1">停止同步 <a class="header-anchor" href="#停止同步" aria-label="Permalink to &quot;停止同步&quot;">​</a></h3><p>在“借网盘同步”里点“停止同步”。这台设备上的数据留着，之后的改动只在这台设备上，网盘里的不动。停止前会先把还没下载到这台设备的附件下载下来；下载不了时会提示，这时仍然停止，这些附件之后就打不开了，最好等联网后再停止。再开启时，会用网盘里的数据替换这台设备上的数据。</p><h2 id="backup" tabindex="-1">备份 <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;备份 {#backup}&quot;">​</a></h2><p>没有借网盘同步时，数据只在这台设备上，设备丢了或坏了，数据也就没了。请定期备份，把备份文件存到别处，比如网盘或另一台电脑。</p><ol><li>打开“设置”，点最上面的“本机模式”，再点“备份”。</li><li>选择保存的位置。备份文件名是 <code>NextTodo-备份-&lt;日期&gt;.tar</code>，以前的版本备份的 <code>.db</code> 文件也能恢复。</li></ol><p>备份里有全部事项、文件夹、附件、改动记录和令牌，不含 AI 整理的配置和 API 密钥。</p><h2 id="恢复" tabindex="-1">恢复 <a class="header-anchor" href="#恢复" aria-label="Permalink to &quot;恢复&quot;">​</a></h2><p>用备份替换这台设备上现在的全部数据：</p><ol><li>打开“设置 → 本机模式”，点“恢复”，选择备份文件。</li><li>确认替换。App 会重新启动，打开后就是备份时的数据。</li></ol><p>恢复前的数据不会删除，仍留在 App 的数据目录里。借网盘同步时不能恢复，要先停止同步。</p><p>换了新设备时，在新设备上选“在本机使用”，再恢复旧设备的备份，就能接着用。</p><p>App 无法启动时，页面上也有“恢复备份”按钮。</p><h2 id="改用服务器" tabindex="-1">改用服务器 <a class="header-anchor" href="#改用服务器" aria-label="Permalink to &quot;改用服务器&quot;">​</a></h2><p>在“设置 → 本机模式”里点“改用服务器”，App 会重新启动，回到登录页。本机的数据保留在这台设备上，以后再选“在本机使用”可以接着用，但不会自动搬到服务器上。借网盘同步的，改用服务器期间同步停下，回到本机使用后接着同步。</p>',32)])])}const b=e(o,[["render",t]]);export{u as __pageData,b as default};
